{
  "css": "#booking-layout {
  padding-top: 20px;
  border-top: 1px solid #ededf0;
}

.booking-host-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  color: #202024;
}

.booking-host-subtitle {
  margin: 4px 0 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.5;
}

.booking-icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  padding: 0;
  margin: 0;
  border: none;
  background-color: transparent;
  cursor: pointer;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}

.booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  color: #60606a;
  transition: color 0.2s ease, transform 0.1s ease;
}

.booking-icon-btn:hover img {
  color: #5146d7;
}

.booking-icon-btn:active img {
  transform: scale(0.92);
}

.booking-icon-btn[aria-pressed="true"] img {
  color: #5146d7;
}

.booking-icon-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
  border-radius: 4px;
}

#booking-actions > button:last-child {
  min-height: 52px;
  padding: 12px 16px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  border-radius: 6px;
  border: none;
  text-align: center;
  width: 100%;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

#booking-actions > button:last-child:hover {
  background-color: #4339b8;
}

#booking-actions > button:last-child:active {
  transform: scale(0.98);
}

#booking-actions > button:last-child:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

.booking-note {
  margin: 12px 0 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
}"
}
